func TestAdd(t *testing.T) {
	if add(2, 3) != 5 {
		t.Fatalf("add(2, 3) = %d, want 5", add(2, 3))
	}
}

func TestAddMixedSigns(t *testing.T) {
	tests := []struct {
		name string
		a    int
		b    int
		want int
	}{
		{name: "positive plus negative", a: 5, b: -3, want: 2},
		{name: "negative plus positive", a: -5, b: 3, want: -2},
		{name: "mixed signs sum to zero", a: 7, b: -7, want: 0},
		{name: "larger negative dominates", a: 4, b: -9, want: -5},
		{name: "larger positive dominates", a: -4, b: 9, want: 5},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := add(tt.a, tt.b)
			if got != tt.want {
				t.Fatalf("add(%d, %d) = %d, want %d", tt.a, tt.b, got, tt.want)
			}
		})
	}
}

